      "A Lei de Introdução às Normas do Direito Brasileiro (LINDB, Decreto-Lei 4.657/1942) não é parte do Código Civil, mas norma de sobredireito que orienta a aplicação de todas as leis brasileiras. Salvo disposição em contrário, a lei começa a vigorar em todo o país 45 dias depois de oficialmente publicada — esse intervalo entre a publicação e a entrada em vigor é chamado de vacatio legis.",
      "Repristinação é o fenômeno pelo qual uma lei revogada volta a vigorar quando a lei que a revogou é, por sua vez, revogada — a LINDB estabelece que a lei revogada não se restaura por ter a lei revogadora perdido a vigência, salvo disposição expressa em contrário: ou seja, a repristinação não é automática no direito brasileiro, precisa estar prevista expressamente na nova lei.",
      "Diante de antinomia (conflito) entre normas, os critérios clássicos de solução são: hierárquico (norma superior prevalece sobre inferior), cronológico (norma posterior revoga a anterior, no mesmo nível hierárquico) e da especialidade (norma especial prevalece sobre a geral, no mesmo assunto) — critérios amplamente utilizados para resolver conflitos aparentes entre dispositivos legais."
