    "corpo": [
      "Personalidade jurídica é a aptidão genérica para ser titular de direitos e deveres na ordem civil — o Código Civil estabelece que a personalidade civil da pessoa começa do nascimento com vida, mas a lei põe a salvo, desde a concepção, os direitos do nascituro (o ser já concebido, mas ainda não nascido). Essa proteção ao nascituro gera intenso debate doutrinário sobre a natureza jurídica exata de sua situação, mas na prática assegura direitos que se consolidam caso ocorra o nascimento com vida.",
      "Capacidade de direito (ou capacidade de gozo) é a aptidão para ser titular de direitos — toda pessoa a possui, desde o nascimento, sem exceção. Capacidade de fato (ou capacidade de exercício) é a aptidão para exercer pessoalmente os atos da vida civil, sem necessidade de representação ou assistência — nem todas as pessoas a possuem plenamente, havendo hipóteses de incapacidade absoluta e relativa previstas em lei.",
      "São absolutamente incapazes apenas os menores de 16 anos (após reforma promovida pelo Estatuto da Pessoa com Deficiência, que restringiu bastante o rol de incapacidade absoluta, retirando dele os antigos casos de deficiência mental e os que não tinham discernimento por causa transitória). São relativamente incapazes: os maiores de 16 e menores de 18 anos, os ébrios habituais e viciados em tóxico, aqueles que, por causa transitória ou permanente, não puderem exprimir sua vontade, e os pródigos."
    ],
