    "corpo": [
      "Bens são classificados de diversas formas: quanto à mobilidade (móveis, que podem ser transportados sem alteração de substância; imóveis, que não podem); quanto à fungibilidade (fungíveis, que podem ser substituídos por outro da mesma espécie, qualidade e quantidade, como dinheiro; infungíveis, que não admitem substituição, como uma obra de arte específica); e quanto à divisibilidade (divisíveis, que podem ser fracionados sem alteração de substância ou valor considerável; indivisíveis, que não podem).",
      "Fato jurídico é todo acontecimento (natural ou humano) capaz de gerar efeitos jurídicos. Ato jurídico é o fato jurídico que decorre de manifestação de vontade humana, mas com efeitos já determinados por lei (não pela vontade das partes). Negócio jurídico é a manifestação de vontade humana que produz efeitos jurídicos escolhidos e queridos pelas próprias partes, dentro dos limites permitidos pela lei — é a categoria mais relevante para contratos e demais relações negociais.",
      "Os planos de existência, validade e eficácia do negócio jurídico formam a chamada 'escada ponteana' (em referência ao jurista Pontes de Miranda): primeiro se verifica se o negócio existe (elementos essenciais presentes: agente, objeto, forma, manifestação de vontade); depois se é válido (agente capaz, objeto lícito/possível/determinado, forma prescrita ou não defesa em lei, ausência de vícios); e por fim se é eficaz (produz efeitos, podendo estar sujeito a condição, termo ou encargo que module essa eficácia)."
    ],
