    "corpo": [
      "Prescrição é a perda da pretensão de exigir judicialmente um direito, pelo decurso do tempo, aplicável aos direitos a uma prestação (direitos que exigem uma conduta de outra pessoa, como pagar uma dívida) — o direito em si não se extingue, mas a possibilidade de exigi-lo judicialmente sim. Decadência é a perda do próprio direito potestativo (direito de criar, modificar ou extinguir uma situação jurídica, sem depender de conduta alheia) pelo decurso do tempo.",
      "O critério mais confiável para diferenciar os dois institutos: se o direito exige uma prestação de outra pessoa (pagar, entregar, fazer), a perda pelo tempo é prescrição; se o direito é exercido unilateralmente, sem depender de conduta alheia (anular um contrato, por exemplo), a perda pelo tempo é decadência. Prazos de prescrição estão concentrados nos arts. 205 (prazo geral de 10 anos) e 206 (prazos especiais, variando de 1 a 5 anos conforme a natureza do direito) do Código Civil; prazos de decadência estão espalhados ao longo de todo o Código, vinculados a cada direito potestativo específico.",
      "Prescrição admite causas de impedimento, suspensão e interrupção (por exemplo, contra os absolutamente incapazes não corre prescrição; interrompida a prescrição, o prazo recomeça a correr por inteiro). Decadência, em regra, não se suspende nem se interrompe, salvo disposição legal em contrário — essa é uma diferença estrutural relevante e frequentemente cobrada entre os dois institutos."
    ],
