    "title": "Contratos: princípios e formação",
    "assunto": "Teoria geral dos contratos",
    "tecnica": "Reconhecimento dos princípios contratuais contemporâneos além da autonomia da vontade",
    "competencia": "Reconhecer os princípios que regem os contratos e o momento de sua formação",
    "dificuldade": "Média",
