    "corpo": [
      "Casamento é ato solene, formal, que exige processo de habilitação prévia e celebração perante autoridade competente (em regra, o juiz de paz ou autoridade equivalente conforme a organização local), gerando efeitos jurídicos a partir da celebração. União estável é a convivência pública, contínua e duradoura entre duas pessoas, estabelecida com o objetivo de constituição de família, reconhecida como entidade familiar mesmo sem qualquer formalidade de celebração — pode, inclusive, ser convertida em casamento mediante pedido ao juiz e assento no registro civil.",
      "O regime de bens define como o patrimônio do casal será tratado durante a união e em caso de sua dissolução. Comunhão parcial de bens é o regime legal supletivo (aplicável quando as partes não escolhem outro, tanto no casamento quanto, por analogia, na união estável): comunicam-se os bens adquiridos onerosamente na constância da união, permanecendo particulares os bens anteriores e os recebidos por doação/herança.",
      "Outros regimes: comunhão universal (comunicam-se todos os bens, presentes e futuros, salvo exceções legais específicas), separação de bens (convencional, por escolha das partes, ou obrigatória, imposta por lei em hipóteses específicas como casamento de maior de 70 anos), e participação final nos aquestos (regime híbrido, em que cada cônjuge administra seu patrimônio individualmente durante a união, mas ao final se apura o que foi adquirido onerosamente por cada um para eventual compensação)."
    ],
    "pontosChave": [
      "Casamento é ato solene com habilitação prévia; união estável é situação de fato reconhecida, sem formalidade de celebração.",
      "Comunhão parcial é o regime legal supletivo — comunica bens adquiridos onerosamente na união, mantém particulares os anteriores/herdados/doados.",
      "Separação obrigatória de bens se impõe por lei em hipóteses específicas (ex.: casamento de maior de 70 anos)."
    ],
