    "corpo": [
      "Sucessão é a transmissão de direitos e obrigações do falecido (de cujus) a seus herdeiros — pode ser legítima (quando a lei determina os herdeiros, na ausência ou insuficiência de testamento) ou testamentária (quando o falecido dispõe de seu patrimônio por testamento, respeitados os limites legais). A abertura da sucessão ocorre no momento da morte (princípio da saisine: a herança se transmite, desde logo, aos herdeiros legítimos e testamentários).",
      "A ordem de vocação hereditária, na sucessão legítima, chama a suceder, nessa ordem: descendentes (em concorrência com o cônjuge/companheiro sobrevivente, conforme o regime de bens), ascendentes (também em concorrência com o cônjuge/companheiro), cônjuge/companheiro sobrevivente (isoladamente, na falta de descendentes e ascendentes), e colaterais até o quarto grau (irmãos, sobrinhos, tios, primos, na falta de todos os anteriores).",
      "Herdeiros necessários (descendentes, ascendentes e cônjuge) têm direito a uma parcela mínima da herança, chamada legítima, correspondente à metade do patrimônio do falecido — o testador só pode dispor livremente, por testamento, da outra metade (parte disponível), se houver herdeiros necessários; na ausência deles, pode dispor da totalidade do patrimônio livremente."
    ],
    "pontosChave": [
      "Sucessão legítima: lei determina herdeiros. Sucessão testamentária: falecido dispõe por testamento, respeitados limites legais.",
      "Ordem de vocação hereditária: descendentes → ascendentes → cônjuge/companheiro (isolado) → colaterais até 4º grau.",
      "Herdeiros necessários (descendentes, ascendentes, cônjuge) têm direito à legítima (metade do patrimônio) — só a outra metade é livremente disponível por testamento."
    ],
